std::wstring PipeName(const GUID& id)
{
    wchar_t guid[guidLength + 1]{};
    if (!StringFromGUID2(id, guid, ARRAYSIZE(guid)))
        return {};
    return std::wstring(pipePrefix) + guid;
}

[[maybe_unused]] std::wstring ParsePipeName(std::wstring_view argument)
{
    if (argument.size() != pipePrefix.size() + guidLength || argument.substr(0, pipePrefix.size()) != pipePrefix)
        return {};
    const std::wstring guid(argument.substr(pipePrefix.size()));
    GUID id{};
    if (guid.front() != L'{' || guid.back() != L'}' || FAILED(CLSIDFromString(guid.c_str(), &id)))
        return {};
    std::wstring canonical = PipeName(id);
    if (canonical.empty() || CompareStringOrdinal(argument.data(), static_cast<int>(argument.size()),
                                                   canonical.c_str(), -1, TRUE) != CSTR_EQUAL)
        return {};
    return canonical;
}

enum class Phase : DWORD { Hello = 1, Accept = 2, Done = 3, AcceptTransferJob = 4 };
struct Frame
{
    DWORD version;
    DWORD capabilityMask;
    Phase phase;
};
static_assert(sizeof(Frame) == 12);

enum ExitCode { Ok, Failed, Cancelled, Untrusted, ProtocolError, Disconnected, TimedOut };

int Report(ExitCode code, const wchar_t* stage, DWORD error)
{
    std::fwprintf(stderr, L"%ls (%lu)\n", stage, error);
    return code;
}

int IoError(const wchar_t* stage, DWORD error)
{
    if (error == ERROR_BROKEN_PIPE || error == ERROR_NO_DATA || error == ERROR_PIPE_NOT_CONNECTED)
        return Report(Disconnected, stage, error);
    return Report(error == ERROR_CANCELLED ? Cancelled : error == ERROR_TIMEOUT ? TimedOut : Failed, stage, error);
}

bool IsStopSignaled(HANDLE stop)
{
    return stop && WaitForSingleObject(stop, 0) == WAIT_OBJECT_0;
}

DWORD FinishIo(HANDLE pipe, OVERLAPPED& io, DWORD& count, ULONGLONG deadline, HANDLE stop = nullptr)
{
    const auto now = GetTickCount64();
    const DWORD remaining = deadline == MAXULONGLONG ? INFINITE :
        now < deadline ? static_cast<DWORD>(deadline - now) : 0;
    const HANDLE events[] = {io.hEvent, stop};
    const DWORD wait = stop ? WaitForMultipleObjects(ARRAYSIZE(events), events, FALSE, remaining)
                            : WaitForSingleObject(io.hEvent, remaining);
    if (wait == WAIT_OBJECT_0)
        return GetOverlappedResult(pipe, &io, &count, FALSE) ? ERROR_SUCCESS : GetLastError();
    const DWORD error = wait == WAIT_OBJECT_0 + 1 ? ERROR_CANCELLED : wait == WAIT_TIMEOUT ? ERROR_TIMEOUT : GetLastError();
    CancelIoEx(pipe, &io);
    // Drain the overlapped operation before its stack storage is released.
    GetOverlappedResult(pipe, &io, &count, TRUE);
    return error;
}

[[maybe_unused]] DWORD Connect(HANDLE pipe, ULONGLONG deadline, HANDLE stop = nullptr)
{
    if (IsStopSignaled(stop))
        return ERROR_CANCELLED;
    const auto event = Adopt(CreateEventW(nullptr, TRUE, FALSE, nullptr));
    if (!event)
        return GetLastError();
    OVERLAPPED io{};
    io.hEvent = event.get();
    if (ConnectNamedPipe(pipe, &io))
        return ERROR_SUCCESS;
    const DWORD error = GetLastError();
    if (error == ERROR_PIPE_CONNECTED)
        return ERROR_SUCCESS;
    DWORD unused = 0;
    return error == ERROR_IO_PENDING ? FinishIo(pipe, io, unused, deadline, stop) : error;
}

DWORD Exchange(HANDLE pipe, Frame& frame, bool send, ULONGLONG deadline, bool byteStream = false, HANDLE stop = nullptr)
{
    if (IsStopSignaled(stop))
        return ERROR_CANCELLED;
    if (GetTickCount64() >= deadline)
        return ERROR_TIMEOUT;
    const auto event = Adopt(CreateEventW(nullptr, TRUE, FALSE, nullptr));
    if (!event)
        return GetLastError();
    OVERLAPPED io{};
    io.hEvent = event.get();
    DWORD count = 0;
    BYTE input[sizeof(Frame) + 1]{};
    const BOOL complete = send ? WriteFile(pipe, &frame, sizeof(frame), &count, &io)
                               : ReadFile(pipe, input, byteStream ? sizeof(frame) : sizeof(input), &count, &io);
    if (!complete)
    {
        const DWORD error = GetLastError();
        const DWORD finished = error == ERROR_IO_PENDING ? FinishIo(pipe, io, count, deadline, stop) : error;
        if (finished != ERROR_SUCCESS)
            return finished;
    }
    if (count != sizeof(frame))
        return ERROR_INVALID_DATA;
    if (!send)
        std::memcpy(&frame, input, sizeof(frame));
    return ERROR_SUCCESS;
}

bool Matches(const Frame& frame, Phase phase, DWORD capability = capabilities)
{
    return frame.version == protocolVersion && frame.capabilityMask == capability && frame.phase == phase;
}

bool LiveInSession(HANDLE peer, DWORD pid)
{
    DWORD selfSession = 0, peerSession = 0;
    return WaitForSingleObject(peer, 0) == WAIT_TIMEOUT &&
           ProcessIdToSessionId(GetCurrentProcessId(), &selfSession) &&
           ProcessIdToSessionId(pid, &peerSession) && selfSession == peerSession;
}

bool ExpectedPipePeer(HANDLE pipe, HANDLE process, DWORD pid, bool server)
{
    ULONG actual = 0;
    const BOOL queried = server ? GetNamedPipeServerProcessId(pipe, &actual)
                                : GetNamedPipeClientProcessId(pipe, &actual);
    return queried && actual == pid && GetProcessId(process) == pid && LiveInSession(process, pid);
}

struct LocalFreeDeleter
{
    void operator()(void* p) const { LocalFree(p); }
};

bool TrustedSid(PSID sid, PSID installer)
{
    return IsWellKnownSid(sid, WinLocalSystemSid) || IsWellKnownSid(sid, WinBuiltinAdministratorsSid) ||
           EqualSid(sid, installer);
}

bool ProtectedObject(HANDLE handle, bool directory, bool namespaceOnly)
{
    FILE_ATTRIBUTE_TAG_INFO info{};
    if (!GetFileInformationByHandleEx(handle, FileAttributeTagInfo, &info, sizeof(info)) ||
        (info.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) ||
        ((info.FileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0) != directory)
        return false;

    PSID owner = nullptr;
    PACL dacl = nullptr;
    PSECURITY_DESCRIPTOR raw = nullptr;
    const DWORD status = GetSecurityInfo(handle, SE_FILE_OBJECT, OWNER_SECURITY_INFORMATION | DACL_SECURITY_INFORMATION,
                                         &owner, nullptr, &dacl, nullptr, &raw);
    const std::unique_ptr<void, LocalFreeDeleter> security(raw);
    PSID installerRaw = nullptr;
    if (status != ERROR_SUCCESS || !owner || !dacl ||
        !ConvertStringSidToSidW(L"S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464", &installerRaw))
        return false;
    const std::unique_ptr<void, LocalFreeDeleter> installer(installerRaw);
    if (!TrustedSid(owner, installer.get()))
        return false;

    // Inherit-only ACEs describe descendants, which we check independently.
    constexpr DWORD commonChange = GENERIC_ALL | GENERIC_WRITE | WRITE_DAC | WRITE_OWNER | DELETE |
                                   FILE_WRITE_EA | FILE_WRITE_ATTRIBUTES | FILE_DELETE_CHILD;
    const DWORD change = commonChange | (namespaceOnly ? 0 : FILE_WRITE_DATA | FILE_APPEND_DATA);
    for (DWORD i = 0; i < dacl->AceCount; ++i)
    {
        void* entry = nullptr;
        if (!GetAce(dacl, i, &entry))
            return false;
        const auto* header = static_cast<const ACE_HEADER*>(entry);
        if (header->AceFlags & INHERIT_ONLY_ACE)
            continue;
        if (header->AceType == ACCESS_DENIED_ACE_TYPE)
            continue;
        if (header->AceType != ACCESS_ALLOWED_ACE_TYPE)
            return false;
        auto* allow = static_cast<ACCESS_ALLOWED_ACE*>(entry);
        if ((allow->Mask & change) && !TrustedSid(&allow->SidStart, installer.get()))
            return false;
    }
    return true;
}

bool ProtectedObject(HANDLE handle, bool directory)
{
    return ProtectedObject(handle, directory, false);
}

[[maybe_unused]] bool MatchesProtocolImage(const std::wstring& path, WORD expectedRole)
{
    // This maps resources without executing code or resolving its imports.
    const HMODULE image = LoadLibraryExW(path.c_str(), nullptr,
        LOAD_LIBRARY_AS_DATAFILE_EXCLUSIVE | LOAD_LIBRARY_AS_IMAGE_RESOURCE);
    if (!image)
        return false;
    const HRSRC resource = FindResourceW(image, MAKEINTRESOURCEW(SAM_UAC_PROTOCOL_RESOURCE), MAKEINTRESOURCEW(10));
    WORD marker[2]{};
    if (resource && SizeofResource(image, resource) == sizeof(marker))
    {
        const HGLOBAL data = LoadResource(image, resource);
        if (const void* bytes = data ? LockResource(data) : nullptr)
            std::memcpy(marker, bytes, sizeof(marker));
    }
    FreeLibrary(image);
    return marker[0] == protocolVersion && marker[1] == expectedRole;
}

class InstallLocation
{
public:
    InstallLocation() = default;
#ifdef SAM_UAC_BROKER_JOB_TEST
    explicit InstallLocation(Handle testDirectory) : directory(std::move(testDirectory)), testLocation(true) {}
    bool IsTestLocation() const { return testLocation; }
#endif
    bool Open()
    {
#ifdef SAM_UAC_THIN_COPY_TEST
        wchar_t enabled[2]{};
        if (GetEnvironmentVariableW(L"SAM_UAC_THIN_UNELEVATED_TEST", enabled, ARRAYSIZE(enabled)) == 1 &&
            enabled[0] == L'1')
        {
            HANDLE rawToken = nullptr;
            if (!OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &rawToken)) return false;
            const auto token = Adopt(rawToken);
            TOKEN_ELEVATION elevation{};
            DWORD tokenBytes = 0;
            if (!GetTokenInformation(token.get(), TokenElevation, &elevation, sizeof(elevation), &tokenBytes) ||
                tokenBytes != sizeof(elevation) || elevation.TokenIsElevated)
                return false;
            wchar_t requested[32768]{};
            const DWORD length = GetEnvironmentVariableW(L"SAM_UAC_THIN_TEST_INSTALL", requested, ARRAYSIZE(requested));
            if (!length || length >= ARRAYSIZE(requested) || length < 4 || requested[1] != L':' || requested[2] != L'\\')
                return false;
            wchar_t absolute[32768]{};
            const DWORD full = GetFullPathNameW(requested, ARRAYSIZE(absolute), absolute, nullptr);
            if (!full || full >= ARRAYSIZE(absolute) || _wcsicmp(requested, absolute) ||
                GetDriveTypeW(std::wstring(requested, 3).c_str()) != DRIVE_FIXED)
                return false;
            auto dir = Adopt(CreateFileW(absolute, FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES | READ_CONTROL,
                FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr, OPEN_EXISTING,
                FILE_FLAG_OPEN_REPARSE_POINT | FILE_FLAG_BACKUP_SEMANTICS, nullptr));
            FILE_ATTRIBUTE_TAG_INFO attrs{};
            if (!dir || !GetFileInformationByHandleEx(dir.get(), FileAttributeTagInfo, &attrs, sizeof(attrs)) ||
                (attrs.FileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) ||
                !(attrs.FileAttributes & FILE_ATTRIBUTE_DIRECTORY))
                return false;
            path = absolute;
            directory = std::move(dir);
            thinTestLocation = true;
            return true;
        }
#endif
        PWSTR rawFolder = nullptr;
        const HRESULT folderResult = SHGetKnownFolderPath(FOLDERID_ProgramFiles, KF_FLAG_DEFAULT_PATH, nullptr, &rawFolder);
        std::unique_ptr<wchar_t, decltype(&CoTaskMemFree)> folder(rawFolder, CoTaskMemFree);
        if (FAILED(folderResult) || !folder)
            return false;
        const std::wstring programFiles(folder.get());
        folder.reset();
        if (programFiles.size() < 3 || programFiles[1] != L':' || programFiles[2] != L'\\' ||
            GetDriveTypeW(programFiles.substr(0, 3).c_str()) != DRIVE_FIXED)
            return false;
        root = OpenDirectory(programFiles);
        if (!root)
            return false;
        path = programFiles + L"\\Open Samandarin UAC";
        directory = OpenDirectory(path);
        return directory != nullptr;
    }

    Handle OpenImage(const wchar_t* image) const
    {
        auto file = Adopt(CreateFileW(ImagePath(image).c_str(), FILE_READ_DATA | FILE_READ_ATTRIBUTES | READ_CONTROL,
                                      FILE_SHARE_READ, nullptr, OPEN_EXISTING,
                                      FILE_FLAG_OPEN_REPARSE_POINT, nullptr));
#ifdef SAM_UAC_THIN_COPY_TEST
        if (thinTestLocation)
        {
            FILE_ATTRIBUTE_TAG_INFO attrs{};
            return file && GetFileInformationByHandleEx(file.get(), FileAttributeTagInfo, &attrs, sizeof(attrs)) &&
                !(attrs.FileAttributes & (FILE_ATTRIBUTE_REPARSE_POINT | FILE_ATTRIBUTE_DIRECTORY))
                ? std::move(file) : Handle{};
        }
#endif
        return file && ProtectedObject(file.get(), false) ? std::move(file) : Handle{};
    }

    std::wstring ImagePath(const wchar_t* image) const { return path + L"\\" + image; }

    bool MatchesProcess(HANDLE process, const wchar_t* image) const
    {
        std::wstring name(32768, L'\0');
        DWORD length = static_cast<DWORD>(name.size());
        if (!QueryFullProcessImageNameW(process, 0, name.data(), &length))
            return false;
        return _wcsicmp(name.c_str(), ImagePath(image).c_str()) == 0;
    }

    const std::wstring& Directory() const { return path; }
    HANDLE DirectoryHandle() const { return directory.get(); }
#ifdef SAM_UAC_THIN_COPY_TEST
    bool IsThinTestLocation() const { return thinTestLocation; }
#endif

private:
    static Handle OpenDirectory(const std::wstring& name)
    {
        auto dir = Adopt(CreateFileW(name.c_str(), FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES | READ_CONTROL,
                                     FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr, OPEN_EXISTING,
                                     FILE_FLAG_OPEN_REPARSE_POINT | FILE_FLAG_BACKUP_SEMANTICS, nullptr));
        return dir && ProtectedObject(dir.get(), true) ? std::move(dir) : Handle{};
    }

    std::wstring path;
    Handle root, directory;
#ifdef SAM_UAC_THIN_COPY_TEST
    bool thinTestLocation = false;
#endif
#ifdef SAM_UAC_BROKER_JOB_TEST
    bool testLocation = false;
#endif
};

